SELECT 1 AS learner_id, '小林' AS learner_name
UNION ALL
SELECT 2 AS learner_id, '小周' AS learner_name;
SELECT VERSION() AS mysql_version;

CREATE TEMPORARY TABLE lesson_resources (
  id BIGINT UNSIGNED PRIMARY KEY,
  title VARCHAR(100) NOT NULL,
  difficulty VARCHAR(20) NOT NULL,
  CHECK (difficulty IN ('beginner', 'intermediate'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO lesson_resources VALUES (1, 'SQL入门', 'beginner');
SELECT id, title, difficulty FROM lesson_resources;

WITH learners AS (
  SELECT 1 AS learner_id UNION ALL SELECT 2
), events AS (
  SELECT 101 AS event_id, 1 AS learner_id
  UNION ALL SELECT 102, 1
)
SELECT l.learner_id, COUNT(e.event_id) AS event_count
FROM learners l LEFT JOIN events e ON e.learner_id = l.learner_id
GROUP BY l.learner_id ORDER BY l.learner_id;

CREATE TEMPORARY TABLE lesson_progress (
  id INT PRIMARY KEY, state VARCHAR(20) NOT NULL,
  KEY idx_lesson_state (state)
) ENGINE=InnoDB;
INSERT INTO lesson_progress VALUES (1, 'not_started');
START TRANSACTION;
UPDATE lesson_progress SET state = 'completed' WHERE id = 1;
ROLLBACK;
SELECT id, state FROM lesson_progress;
EXPLAIN SELECT id FROM lesson_progress WHERE state = 'not_started';
